"""Capture the collector-facing schema from a separately supplied Hermes release.

Ordinary tests load the SQL snapshot and never import Hermes. Run this module
with the exact release on PYTHONPATH and its existing interpreter to recapture
or independently check the snapshot; see CONTRIBUTING.md.
"""
from __future__ import annotations

import argparse
import os
import sqlite3
import tempfile
from pathlib import Path

from tests.fixtures.make_home import make_home

TABLES = ("system_prompts", "sessions", "messages", "session_turn_leases", "async_delegations", "state_meta")
HEADER = """-- Collector-facing schema captured from Hermes Agent v0.22.0.
-- Commit: e06df9c2eae6901f4c88f464e0ae6e753c0428b8
-- Source: https://github.com/NousResearch/hermes-agent/tree/e06df9c2eae6901f4c88f464e0ae6e753c0428b8
-- Generated by tests/fixtures/capture_release_schema.py from a fresh SessionDB.
-- Tables and their explicit indexes only; no data, FTS objects, or triggers.
-- system_prompts is included for the sessions foreign-key dependency.
-- SQL copyright (c) 2025 Nous Research, MIT License; see hermes-schema-LICENSE.txt.

"""


def schema_sql(conn: sqlite3.Connection) -> str:
    """Preserve sqlite_schema SQL verbatim, ordered tables before indexes."""
    placeholders = ",".join("?" for _ in TABLES)
    rows = conn.execute(
        f"SELECT sql FROM sqlite_schema WHERE tbl_name IN ({placeholders}) "
        "AND type IN ('table', 'index') AND sql IS NOT NULL "
        "ORDER BY CASE type WHEN 'table' THEN 0 ELSE 1 END, name",
        TABLES,
    ).fetchall()
    return HEADER + "\n\n".join(row[0] + ";" for row in rows) + "\n"


def capture() -> str:
    with tempfile.TemporaryDirectory(prefix="hermes-schema-capture-") as temporary:
        home = make_home(Path(temporary) / "hermes-home")
        previous = os.environ.get("HERMES_HOME")
        os.environ["HERMES_HOME"] = str(home)
        try:
            # Import only after routing the host to a fictional, temporary home.
            from hermes_state import SessionDB

            (home / "state.db").unlink()
            session_db = SessionDB(db_path=home / "state.db")
            session_db.close()
            with sqlite3.connect(home / "state.db") as conn:
                return schema_sql(conn)
        finally:
            if previous is None:
                os.environ.pop("HERMES_HOME", None)
            else:
                os.environ["HERMES_HOME"] = previous


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", type=Path, help="compare the captured SQL with this snapshot")
    args = parser.parse_args()
    captured = capture()
    if args.check:
        if args.check.read_text(encoding="utf-8") != captured:
            parser.exit(1, "Release SessionDB schema differs from the snapshot\n")
        print("Release SessionDB schema matches the snapshot")
    else:
        print(captured, end="")


if __name__ == "__main__":
    main()
